      - NODE_ENV=production
      - DB_HOST=postgres
      - DB_NAME=secureapp
      - DB_USER=appuser
      - DB_PASSWORD=securepassword
    depends_on:
      - postgres
    volumes:
      - ./secure:/app
      - /app/node_modules

  postgres:
    image: postgres:15-alpine
    environment:
      - POSTGRES_DB=secureapp
      - POSTGRES_USER=appuser
      - POSTGRES_PASSWORD=securepassword
    volumes:
      - postgres-data:/var/lib/postgresql/data
    ports:
      - "5432:5432"

volumes:
  postgres-data:
